preConditionHook:
// GUARD (2026-09-17): a level's EXISTENCE is a bool set where the scan finds
// it, never a test of the price against -1 -- a back-adjusted series can print
// -1.00 (or 0.00) as a real price. The EL twin guards on the bar index
// (SwingLowBar / SwingHighBar <> -1, VERIFIED), a count and not a price.
// Mentions of the -1 SENTINEL below describe what EL's SwingLow / SwingHigh
// return, not how this rule guards it.
// BROOKS'S UNIVERSAL COUNTERTREND TRIGGER: buy at or below the low of a prior
// swing low, expecting the breakout of it to fail. The bar's low trades at or
// below the most recent CONFIRMED swing low, by at least offsetTicks; the
// short mirrors at the most recent swing high.
//
// Eleven mined candidates collapse to this one condition. Seven are the plain
// limit trigger differing only in the CONTEXT GATE they attach -- range
// bottom, bull channel, bear channel, pullback in a bull trend, late-stage
// channel -- every one of which is a rule in another bucket that the entry
// pane ANDs, so none of them changes this test. Two more are its NEGATION (the
// test undershoots the old extreme), which is the per-placement negate toggle.
// The scale-in sizing two of them attach is not expressible and is dropped.
//
// offsetTicks DEFAULTS TO 0, not Brooks's "one tick below": the standing
// convention mechanizes a limit fill as a signal-bar close with the fill at
// the next bar's open, so the extra tick has nowhere to land. Ticks are division-first,
// ctx.MinMove() / ctx.PriceScale() computed once into tickSz; both are
// per-symbol constants (VERIFIED, one change print per chart, at bar 1).
//
// THE -1 SENTINEL is guarded explicitly: a window with no pivot leaves the
// level at -1, which as a PRICE sits under every real price, so an unguarded
// long would read every bar as an undercut.
//
// THE PIVOT IS READ AT THE CURRENT BAR, not lagged. The newest pivot the scan
// can return sits exactly `strength` bars back (confirmation lag MEASURED as
// exactly Strength, never 0 or 1), so bar 0 can never be the pivot it is
// compared against, and no lagged read of a swing function -- which has no
// register row -- is needed.
//
// PIVOT SCAN inlined from SwingHigh.json per the B-list decision. MEASURED
// (EL_Swing_Probe.txt, @ES 60 min): the pivot bar is AT OR ABOVE the `strength`
// OLDER bars and STRICTLY ABOVE the `strength` NEWER bars -- bars-ago indexing,
// so the newer bars are the smaller k and take el_gt / el_lt, the older el_ge /
// el_le; lag exactly `strength`; candidate offsets strength..maxBarsBack-1,
// with the neighbourhood reaching `strength` bars past the window, so the
// deepest bar touched is maxBarsBack - 1 + strength. Scanning newest-first
// with a break reproduces occurrence 1. The comparisons carry the 2.22e-12
// relational tolerance. The low side's tie sense is the mirror of the measured
// high-side rule. No WFSafe_SwingHigh exists, so plain EL governs.
//
// Not SwingPointTestHolds, which requires the low to come NEAR the pivot
// WITHOUT breaking it. Not FailedSwingBreakoutReversal, which is this undercut
// AND the close back above the pivot -- the whole reversal, where this is the
// undercut alone and fires on far more bars. Not StopRunReversalBar, whose
// level is a plain N-bar window extreme.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
tickSz = ctx.MinMove() / ctx.PriceScale();
pivS = (int)strength;
pivW = (int)maxBarsBack;
swHiPx = 0.0;
haveHi = false;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) { swHiPx = high[j]; haveHi = true; break; }
}
swLoPx = 0.0;
haveLo = false;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) { swLoPx = low[j]; haveLo = true; break; }
}
